const Database = global.get('Database');
const db = new Database('hgm_database.db');
db.pragma('journal_mode = WAL');

db.exec(`
CREATE TABLE IF NOT EXISTS users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  username TEXT UNIQUE NOT NULL,
  email TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  password_salt TEXT NOT NULL,
  role TEXT NOT NULL DEFAULT 'member',
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS credentials (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  type TEXT NOT NULL,
  credential_value TEXT NOT NULL,
  label TEXT,
  created_at TEXT NOT NULL,
  FOREIGN KEY(user_id) REFERENCES users(id)
);
CREATE TABLE IF NOT EXISTS access_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER,
  method TEXT NOT NULL,
  time TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS sessions (
  token TEXT PRIMARY KEY,
  user_id INTEGER NOT NULL,
  expires_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS password_resets (
  token TEXT PRIMARY KEY,
  user_id INTEGER NOT NULL,
  expires_at TEXT NOT NULL
);
`);

global.set('db', db);

const existing = db.prepare('SELECT COUNT(*) AS c FROM users').get();
if (existing.c === 0) {
    const crypto = global.get('crypto');
    const salt = crypto.randomBytes(16).toString('hex');
    const hash = crypto.scryptSync('admin123', salt, 64).toString('hex');
    db.prepare('INSERT INTO users (username, email, password_hash, password_salt, role, created_at) VALUES (?,?,?,?,?,?)')
      .run('admin', 'admin@hgm.local', hash, salt, 'admin', new Date().toISOString());
    node.warn('Da tao tai khoan admin mac dinh: admin / admin123 - hay doi mat khau ngay sau khi test!');
}

global.set('doorStatus', {
    state: 'locked',
    method: null,
    user: null,
    lockdown: false,
    updatedAt: new Date().toISOString()
});

return null;

// Payload format
const db = global.get('db');
const body = msg.payload || {};

const cred = db.prepare('SELECT * FROM credentials WHERE type = ? AND credential_value = ?').get(body.type, body.value);

if (!cred) {
    const resultMsg = { payload: { cmd: 'DENY' } };
    return [resultMsg, null];
}

const user = db.prepare('SELECT * FROM users WHERE id = ?').get(cred.user_id);
const now = new Date().toISOString();

db.prepare('INSERT INTO access_logs (user_id, method, time) VALUES (?,?,?)').run(user.id, body.type, now);

const prevStatus = global.get('doorStatus') || {};
global.set('doorStatus', {
    state: 'unlocked',
    method: body.type,
    user: user.username,
    lockdown: prevStatus.lockdown || false,
    updatedAt: now
});

const resultMsg = { payload: { cmd: 'GRANT' } };
const sheetsMsg = { payload: { time: now, user: user.username, method: body.type } };
return [resultMsg, sheetsMsg];

const TELEGRAM_TOKEN = 'YOUR_BOT_TOKEN';
const CHAT_ID = 'YOUR_CHAT_ID';

const text = 'CANH BAO HGM: phat hien bat thuong tai cua (' + (msg.payload.reason || 'khong ro') + ') luc ' + new Date().toLocaleString('vi-VN');

msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.url = 'https://api.telegram.org/bot' + TELEGRAM_TOKEN + '/sendMessage';
msg.payload = { chat_id: CHAT_ID, text: text };
return msg;

const db = global.get('db');
const authHeader = (msg.req && msg.req.headers['authorization']) || '';
const token = authHeader.replace('Bearer ', '').trim();

msg.authUser = null;
msg.authError = null;

if (!token) {
    msg.authError = 'Thieu token dang nhap';
} else {
    const session = db.prepare('SELECT * FROM sessions WHERE token = ?').get(token);
    if (!session || new Date(session.expires_at) < new Date()) {
        msg.authError = 'Token khong hop le hoac da het han';
    } else {
        msg.authUser = db.prepare('SELECT id, username, email, role FROM users WHERE id = ?').get(session.user_id);
    }
}
return msg;

const db = global.get('db');
const crypto = global.get('crypto');
const body = msg.payload || {};

if (!body.username || !body.email || !body.password) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'Thieu username/email/password' };
    return msg;
}
if (body.password.length < 6) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'Mat khau toi thieu 6 ky tu' };
    return msg;
}

const existing = db.prepare('SELECT id FROM users WHERE username = ? OR email = ?').get(body.username, body.email);
if (existing) {
    msg.statusCode = 409;
    msg.payload = { ok: false, error: 'Username hoac email da ton tai' };
    return msg;
}

const salt = crypto.randomBytes(16).toString('hex');
const hash = crypto.scryptSync(body.password, salt, 64).toString('hex');

db.prepare('INSERT INTO users (username, email, password_hash, password_salt, role, created_at) VALUES (?,?,?,?,?,?)')
  .run(body.username, body.email, hash, salt, 'member', new Date().toISOString());

msg.payload = { ok: true, message: 'Dang ky thanh cong, hay dang nhap' };
return msg;

const db = global.get('db');
const crypto = global.get('crypto');
const body = msg.payload || {};

const user = db.prepare('SELECT * FROM users WHERE username = ?').get(body.username);
if (!user) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: 'Sai username hoac mat khau' };
    return msg;
}

const hash = crypto.scryptSync(body.password || '', user.password_salt, 64).toString('hex');
if (hash !== user.password_hash) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: 'Sai username hoac mat khau' };
    return msg;
}

const token = crypto.randomBytes(32).toString('hex');
const expires = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();

db.prepare('INSERT INTO sessions (token, user_id, expires_at) VALUES (?,?,?)').run(token, user.id, expires);

msg.payload = {
    ok: true,
    token: token,
    user: { id: user.id, username: user.username, email: user.email, role: user.role }
};
return msg;

const db = global.get('db');
const authHeader = (msg.req && msg.req.headers['authorization']) || '';
const token = authHeader.replace('Bearer ', '').trim();
if (token) db.prepare('DELETE FROM sessions WHERE token = ?').run(token);
msg.payload = { ok: true };
return msg;

const db = global.get('db');
const crypto = global.get('crypto');
const email = (msg.payload || {}).email;

const user = db.prepare('SELECT * FROM users WHERE email = ?').get(email);
if (user) {
    const token = crypto.randomBytes(24).toString('hex');
    const expires = new Date(Date.now() + 15 * 60 * 1000).toISOString();
    db.prepare('INSERT INTO password_resets (token, user_id, expires_at) VALUES (?,?,?)').run(token, user.id, expires);
    // Local/dev: chua noi SMTP that, nen in link ra log Node-RED de test.
    // Khi trien khai that, thay bang node gui email that (vd: SendGrid, Gmail SMTP).
    node.warn('[DEV] Link dat lai mat khau cho ' + email + ': reset-password.html?token=' + token);
}

// Luon tra ve cung 1 thong bao du email co ton tai hay khong, tranh lo thong tin tai khoan
msg.payload = { ok: true, message: 'Neu email ton tai trong he thong, huong dan dat lai mat khau da duoc gui' };
return msg;

const db = global.get('db');
const crypto = global.get('crypto');
const body = msg.payload || {};

const record = db.prepare('SELECT * FROM password_resets WHERE token = ?').get(body.token);
if (!record || new Date(record.expires_at) < new Date()) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'Token khong hop le hoac da het han' };
    return msg;
}
if (!body.newPassword || body.newPassword.length < 6) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'Mat khau moi toi thieu 6 ky tu' };
    return msg;
}

const salt = crypto.randomBytes(16).toString('hex');
const hash = crypto.scryptSync(body.newPassword, salt, 64).toString('hex');
db.prepare('UPDATE users SET password_hash = ?, password_salt = ? WHERE id = ?').run(hash, salt, record.user_id);
db.prepare('DELETE FROM password_resets WHERE token = ?').run(body.token);
db.prepare('DELETE FROM sessions WHERE user_id = ?').run(record.user_id);

msg.payload = { ok: true, message: 'Dat lai mat khau thanh cong, hay dang nhap lai' };
return msg;

if (msg.authError) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: msg.authError };
    return msg;
}
msg.payload = global.get('doorStatus') || {};
return msg;

if (msg.authError) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: msg.authError };
    return msg;
}
const db = global.get('db');
const limit = parseInt(msg.req.query.limit) || 20;
const rows = db.prepare(`
    SELECT al.time AS time, al.method AS method, u.username AS user
    FROM access_logs al
    LEFT JOIN users u ON u.id = al.user_id
    ORDER BY al.id DESC
    LIMIT ?
`).all(limit);
msg.payload = rows;
return msg;

if (msg.authError) {
    const errMsg = { statusCode: 401, payload: { ok: false, error: msg.authError }, res: msg.res };
    return [null, errMsg];
}

const db = global.get('db');
const now = new Date().toISOString();
db.prepare('INSERT INTO access_logs (user_id, method, time) VALUES (?,?,?)').run(msg.authUser.id, 'remote_web', now);

const prevStatus = global.get('doorStatus') || {};
global.set('doorStatus', {
    state: 'unlocked',
    method: 'remote_web',
    user: msg.authUser.username,
    lockdown: prevStatus.lockdown || false,
    updatedAt: now
});

const cmdMsg = { payload: { cmd: 'UNLOCK' } };
const respMsg = { payload: { ok: true, message: 'Da gui lenh mo cua' }, res: msg.res };
return [cmdMsg, respMsg];

if (msg.authError) {
    const errMsg = { statusCode: 401, payload: { ok: false, error: msg.authError }, res: msg.res };
    return [null, errMsg];
}

const enable = !!(msg.payload && msg.payload.enable);
const status = global.get('doorStatus') || {};
status.lockdown = enable;
status.updatedAt = new Date().toISOString();
global.set('doorStatus', status);

const cmdMsg = { payload: { cmd: enable ? 'LOCKDOWN_ON' : 'LOCKDOWN_OFF' } };
const respMsg = { payload: { ok: true, lockdown: enable }, res: msg.res };
return [cmdMsg, respMsg];

if (msg.authError) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: msg.authError };
    return msg;
}
if (msg.authUser.role !== 'admin') {
    msg.statusCode = 403;
    msg.payload = { ok: false, error: 'Chi admin duoc phep' };
    return msg;
}
const db = global.get('db');
msg.payload = db.prepare('SELECT id, username, email, role, created_at FROM users').all();
return msg;

if (msg.authError) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: msg.authError };
    return msg;
}
if (msg.authUser.role !== 'admin') {
    msg.statusCode = 403;
    msg.payload = { ok: false, error: 'Chi admin duoc phep' };
    return msg;
}
const db = global.get('db');
msg.payload = db.prepare('SELECT id, type, credential_value, label, created_at FROM credentials WHERE user_id = ?').all(msg.req.params.id);
return msg;

if (msg.authError) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: msg.authError };
    return msg;
}
if (msg.authUser.role !== 'admin') {
    msg.statusCode = 403;
    msg.payload = { ok: false, error: 'Chi admin duoc phep' };
    return msg;
}

const db = global.get('db');
const body = msg.payload || {};
if (!body.type || !body.value) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'Thieu type/value' };
    return msg;
}

db.prepare('INSERT INTO credentials (user_id, type, credential_value, label, created_at) VALUES (?,?,?,?,?)')
  .run(msg.req.params.id, body.type, body.value, body.label || '', new Date().toISOString());

msg.payload = { ok: true, message: 'Da them thong tin xac thuc' };
return msg;

if (msg.authError) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: msg.authError };
    return msg;
}
if (msg.authUser.role !== 'admin') {
